"""Thin client for the world MCP server.

api(action, ...) where action is one of:
  'search' -> api_search(query, top_k)
  'fetch'  -> api_fetch(method, url, params=None, body=None)
  'get'    -> GET url (params dict/str optional)
  'post'   -> POST url (body dict/str optional)
  'patch'  -> PATCH url
  'put'    -> PUT url
  'delete' -> DELETE url
  'b64'    -> base64url-encode text
Returns the raw text result from the MCP tool.
"""
import json, urllib.request

MCP_URL = "http://127.0.0.1:33975/mcp/4b9920c26f88380926c838c2e34422e0"


def _rpc(payload, sid=None, url=MCP_URL):
    req = urllib.request.Request(url, data=json.dumps(payload).encode(),
                                 headers={"Content-Type": "application/json",
                                          "Accept": "application/json, text/event-stream"})
    if sid:
        req.add_header("Mcp-Session-Id", sid)
    with urllib.request.urlopen(req, timeout=60) as r:
        body = r.read().decode()
        sid_out = r.headers.get("Mcp-Session-Id")
    data = None
    for line in body.splitlines():
        if line.startswith("data:"):
            data = json.loads(line[5:].strip())
    if data is None and body.strip():
        data = json.loads(body)
    return data, sid_out


def _session():
    init = {"jsonrpc": "2.0", "id": 1, "method": "initialize",
            "params": {"protocolVersion": "2024-11-05", "capabilities": {},
                       "clientInfo": {"name": "agent", "version": "1"}}}
    _, sid = _rpc(init)
    try:
        _rpc({"jsonrpc": "2.0", "method": "notifications/initialized"}, sid)
    except Exception:
        pass
    return sid


def _call(name, args):
    sid = _session()
    res, _ = _rpc({"jsonrpc": "2.0", "id": 2, "method": "tools/call",
                   "params": {"name": name, "arguments": args}}, sid)
    if "error" in res:
        return "MCP_ERROR: " + json.dumps(res["error"])
    try:
        content = res["result"]["content"]
        return "\n".join(c["text"] for c in content if c.get("type") == "text")
    except Exception:
        return json.dumps(res)


def _norm(x):
    return json.dumps(x) if isinstance(x, (dict, list)) else x


def api(action, url=None, value=None, extra=None):
    a = (action or "").lower()
    if a == "search":
        return _call("api_search", {"query": url, "top_k": int(value or 5)})
    if a == "fetch":
        return _call("api_fetch", {"method": value, "url": url,
                                   "params": _norm(extra), "body": None})
    if a in ("get", "delete"):
        return _call("api_fetch", {"method": a.upper(), "url": url,
                                   "params": _norm(value), "body": None})
    if a in ("post", "put", "patch"):
        return _call("api_fetch", {"method": a.upper(), "url": url,
                                   "params": _norm(extra), "body": _norm(value)})
    if a == "b64":
        return _call("base64_encode", {"text": url})
    return "unknown action: " + str(action)

